        private System.Drawing.Bitmap DrawLicenseHeaderIcon(int width, int height)
        {
            System.Drawing.Bitmap bmp = new System.Drawing.Bitmap(width, height);
            using (System.Drawing.Graphics g = System.Drawing.Graphics.FromImage(bmp))
            {
                g.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
                g.Clear(System.Drawing.Color.Transparent);

                // Draw Card Base
                using (System.Drawing.Drawing2D.GraphicsPath path = new System.Drawing.Drawing2D.GraphicsPath())
                {
                    int r = 8;
                    path.AddArc(4, 4, r * 2, r * 2, 180, 90);
                    path.AddArc(width - 4 - r * 2, 4, r * 2, r * 2, 270, 90);
                    path.AddArc(width - 4 - r * 2, height - 4 - r * 2, r * 2, r * 2, 0, 90);
                    path.AddArc(4, height - 4 - r * 2, r * 2, r * 2, 90, 90);
                    path.CloseAllFigures();

                    using (System.Drawing.SolidBrush brush = new System.Drawing.SolidBrush(System.Drawing.Color.FromArgb(240, 244, 250)))
                    {
                        g.FillPath(brush, path);
                    }
                    using (System.Drawing.Pen pen = new System.Drawing.Pen(System.Drawing.Color.FromArgb(0, 102, 204), 2.5f))
                    {
                        g.DrawPath(pen, path);
                    }
                }

                // Card Header Bar
                using (System.Drawing.SolidBrush headerBrush = new System.Drawing.SolidBrush(System.Drawing.Color.FromArgb(0, 102, 204)))
                {
                    g.FillRectangle(headerBrush, 5, 5, width - 10, 18);
                }

                // Photo Box
                using (System.Drawing.SolidBrush photoBrush = new System.Drawing.SolidBrush(System.Drawing.Color.FromArgb(200, 215, 235)))
                {
                    g.FillRectangle(photoBrush, 12, 28, 22, 28);
                }
                using (System.Drawing.Pen pen = new System.Drawing.Pen(System.Drawing.Color.FromArgb(100, 140, 180), 1f))
                {
                    g.DrawRectangle(pen, 12, 28, 22, 28);
                }

                // Photo Silhouette
                using (System.Drawing.SolidBrush headBrush = new System.Drawing.SolidBrush(System.Drawing.Color.FromArgb(100, 130, 170)))
                {
                    g.FillEllipse(headBrush, 18, 32, 10, 10);
                    g.FillPie(headBrush, 15, 43, 16, 16, 180, 180);
                }

                // Text Lines
                using (System.Drawing.SolidBrush lineBrush = new System.Drawing.SolidBrush(System.Drawing.Color.FromArgb(80, 100, 130)))
                {
                    g.FillRectangle(lineBrush, 40, 30, 32, 4);
                    g.FillRectangle(lineBrush, 40, 38, 26, 4);
                    g.FillRectangle(lineBrush, 40, 46, 30, 4);
                    g.FillRectangle(lineBrush, 12, 60, 58, 4);
                }
            }
            return bmp;
        }

